CREATE TABLE teams (
  id   INT IDENTITY PRIMARY KEY,
  name NVARCHAR(100) NOT NULL
);

CREATE TABLE users (
  id         INT IDENTITY CONSTRAINT PK_users PRIMARY KEY,
  email      NVARCHAR(256) NOT NULL CONSTRAINT UQ_users_email UNIQUE,
  age        INT NULL CONSTRAINT CK_users_age CHECK (age >= 0),
  team_id    INT NULL CONSTRAINT FK_users_team REFERENCES teams(id) ON DELETE SET NULL,
  created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME()
);
